            r"Florida|Georgia|Hawaii|Idaho|Illinois|Indiana|Iowa|Kansas|Kentucky|"
            r"Louisiana|Maine|Maryland|Massachusetts|Michigan|Minnesota|Mississippi|"
            r"Missouri|Montana|Nebraska|Nevada|New Hampshire|New Jersey|New Mexico|"
            r"New York|North Carolina|North Dakota|Ohio|Oklahoma|Oregon|Pennsylvania|"
            r"Rhode Island|South Carolina|South Dakota|Tennessee|Texas|Utah|Vermont|"
            r"Virginia|Washington|West Virginia|Wisconsin|Wyoming"
        )
        state_abbrev_pat = (
            r"AL|AK|AZ|AR|CA|CO|CT|DE|FL|GA|HI|ID|IL|IN|IA|KS|KY|LA|ME|MD|MA|MI|"
            r"MN|MS|MO|MT|NE|NV|NH|NJ|NM|NY|NC|ND|OH|OK|OR|PA|RI|SC|SD|TN|TX|UT|"
            r"VT|VA|WA|WV|WI|WY"
        )
        extra_location_pat = (
            r"Puerto Rico|Alberta|British Columbia|Manitoba|New Brunswick|"
            r"Newfoundland and Labrador|Nova Scotia|Ontario|Quebec|Saskatchewan"
        )
        state_name_re = re.compile(r"\b(?:%s)\b" % state_name_pat, re.I)
        state_abbrev_re = re.compile(r"\b(?:%s)\b" % state_abbrev_pat)
        extra_location_re = re.compile(r"\b(?:%s)\b" % extra_location_pat, re.I)
        inspection_pat = re.compile(
            r"(?i)\b(?:inspected|inspection of|conducted an inspection|performed an on-site "
            r"investigation|conducted an investigation|investigated|reviewed|review of|"
            r"virtually inspected|observed excavation|acting as agents of PHMSA)\b"
        )
        subject_pat = re.compile(
            r"(?i)\b(?:pipeline|pipelines|pipeline system|pipeline systems|facility|facilities|"
            r"control room|distribution system|distribution systems|drug and alcohol|"
            r"integrity management|records|procedures|operations|maintenance|program|"
            r"station|compressor station|compressor|terminal|plant|storage facility|"
            r"storage facilities|underground natural gas storage|UNGSF|segment|lateral|"
            r"line [A-Z0-9#\\-]+|construction project|construction records|incident|release|"
            r"assets|annual report records)\b"
        )
        direct_location_pat = re.compile(
            r"(?i)\b(?:located in|located at|facility in|facilities in|facility located in|"
            r"pipeline system located in|pipeline systems located in|pipeline system in|"
            r"pipeline systems in|distribution system in|distribution systems in|"
            r"control room in|terminal in|plant in|station in|storage facility in|"
            r"storage facilities in|underground natural gas storage facilities in|"
            r"records and facilities|records, procedures and facilities|near [A-Z][A-Za-z .'-]+,\s*"
            r"(?:%s|%s)|at [0-9A-Za-z .#&'/-]+,\s*[A-Z][A-Za-z .'-]+,\s*(?:%s|%s))\b"
            % (state_name_pat, state_abbrev_pat, state_name_pat, state_abbrev_pat)
        )
        stop_pat = re.compile(
            r"(?i)\b(?:As a result of the inspection|As a result of the investigation|"
            r"Based on the inspection|The items? inspected|The items? investigated|"
            r"The item inspected|The item investigated)\b"
        )

        def norm(text: str) -> str:
            return " ".join((text or "").split())

        def has_state(text: str) -> bool:
            return bool(
                state_name_re.search(text or "")
                or state_abbrev_re.search(text or "")
                or extra_location_re.search(text or "")
            )

        def trim(text: str) -> str:
            text = norm(text)
            if not text:
                return ""
            dear_m = re.search(r"Dear [^:]{0,120}:\s*", text[:500])
            if dear_m:
                text = text[dear_m.end() :].strip()
            m = stop_pat.search(text)
            if m and m.start() > 0:
                text = text[: m.start()].rstrip(" ;,")
            text = re.sub(r",?\s+and the Gulf of Mexico\b", "", text, flags=re.I)
            text = re.sub(r",?\s+in the Gulf of Mexico\b", "", text, flags=re.I)
            return text

        def sentence_split(text: str) -> list[str]:
            parts = [norm(part) for part in re.split(r"(?<=[.!?])\s+", norm(text))]
            return [part for part in parts if part]

        def paragraph_score(text: str) -> tuple[int, str]:
            text = trim(text)
            if not text or not has_state(text):
                return (0, "")

            sents = sentence_split(text)
            if not sents:
                sents = [text]

            matched = []
            for sent in sents:
                if not has_state(sent):
                    continue
                if direct_location_pat.search(sent):
                    matched.append(sent)
                    continue
                if inspection_pat.search(sent) and subject_pat.search(sent):
                    matched.append(sent)
                    continue
                if subject_pat.search(sent) and re.search(r"(?i)\b(?:in|near|at|throughout|across)\b", sent):
                    matched.append(sent)

            if matched:
                snippet = " ".join(matched)
                score = 3 if any(direct_location_pat.search(sent) for sent in matched) else 2
                return (score, snippet)

            if direct_location_pat.search(text):
                return (2, text)
            if inspection_pat.search(text) and subject_pat.search(text):
                return (1, text)
            return (0, "")

        def add(out: list[dict], seen: set[tuple], text: str, page_no=None, paragraph_no=None, line_no=None):
            text = norm(text)
            if not text:
                return
            key = (text.lower(), page_no, paragraph_no, line_no)
            if key in seen:
                return
            seen.add(key)
            span = {"text": text}
            if page_no is not None:
                span["page_no"] = page_no
            if paragraph_no is not None:
                span["paragraph_no"] = paragraph_no
            if line_no is not None:
                span["line_no"] = line_no
            out.append(span)

        out: list[dict] = []
        seen: set[tuple] = set()

        for item in (doc.get("paragraphs") or [])[:12]:
            trimmed = trim(item.get("text", ""))
            if not trimmed or not has_state(trimmed):
                continue
            if not (inspection_pat.search(trimmed) or direct_location_pat.search(trimmed)):
                continue
            add(out, seen, trimmed, page_no=item.get("page_no"), paragraph_no=item.get("paragraph_no"))
            return out[:1]

        best = None
        for item in (doc.get("paragraphs") or [])[:18]:
            score, snippet = paragraph_score(item.get("text", ""))
            if score <= 0:
                continue
            candidate = (
                score,
                item.get("page_no", 10**9),
                item.get("paragraph_no", 10**9),
                snippet,
                item.get("page_no"),
                item.get("paragraph_no"),
            )
            if best is None or score > best[0] or (score == best[0] and candidate[1:3] < best[1:3]):
                best = candidate
                if score >= 3:
                    break

        if best is not None:
            add(out, seen, best[3], page_no=best[4], paragraph_no=best[5])
            return out[:1]

        lines = [item for item in (doc.get("lines") or [])[:80] if item.get("text", "").strip()]
        dear_idx = None
        for idx, item in enumerate(lines):
            if "Dear " in item.get("text", ""):
                dear_idx = idx
                break
        if dear_idx is not None:
            intro_lines = []
            for item in lines[dear_idx + 1 : dear_idx + 12]:
                text = norm(item.get("text", ""))
                if not text:
                    continue
                if re.search(r"(?i)^As a result of the inspection|^As a result of the investigation|^Based on the inspection", text):
                    break
                intro_lines.append(item)
            if intro_lines:
                merged = norm(" ".join(item["text"] for item in intro_lines))
                score, snippet = paragraph_score(merged)
                if score > 0:
                    add(out, seen, snippet, page_no=intro_lines[0].get("page_no"), line_no=intro_lines[0].get("line_no"))
                    return out[:1]

        return out[:1]
    except Exception:
        return []

import re


_PART_RE = r"(?:40|1\d\d|2\d\d)\.\d+(?:\([A-Za-z0-9]+\))*"
_CITE_RE = re.compile(
    rf"((?:49\s*C\.?\s*F\.?\s*R\.?\s*)?§\s*{_PART_RE}|section[s]?\s+{_PART_RE})",
    re.IGNORECASE,
)
_STOP_RE = re.compile(
    r"^(proposed civil penalty|warning items|proposed compliance order|response to this notice)\b",
    re.IGNORECASE,
)
_ALLEGATION_RE = re.compile(
    r"\b(failed|did not|didn't|was not|were not|has not|have not)\b",
    re.IGNORECASE,
)
_EARLY_ALLEGATION_RE = re.compile(
    r"^\s*(?:therefore,?\s+|thus,?\s+)?[^§\n]{0,100}\b(failed|did not|didn't|was not|were not|has not|have not)\b",
    re.IGNORECASE,
)
_CONCLUSION_RE = re.compile(r"^\s*(therefore|thus)\b", re.IGNORECASE)
_SECTION_START_RE = re.compile(r"(item inspected|items inspected)", re.IGNORECASE)
_PART_RE = r"(?:40|1\d\d|2\d\d)\.\d+(?:\([A-Za-z0-9]+\))*"
_LEAD_CITE_RE = re.compile(rf"(?:§+|section[s]?)\s*({_PART_RE})", re.IGNORECASE)
_FOLLOW_CITE_RE = re.compile(rf"\b(?:and|or|,)\s*({_PART_RE})", re.IGNORECASE)


def _line_window(lines):
    start_idx = None
    for idx in range(len(lines)):
        window = " ".join(" ".join(lines[j]["text"].lower().split()) for j in range(idx, min(len(lines), idx + 3)))
        if _SECTION_START_RE.search(window) and "probable violation" in window:
            start_idx = idx + 1
            break

    if start_idx is None:
        return

    for line in lines[start_idx:]:
        text = line["text"].strip()
        if _STOP_RE.match(text):
            break
        yield line


def rule_citation_lines(doc: dict) -> list[dict]:
    try:
        spans = []
        seen = set()
        for line in _line_window(doc.get("lines", [])):
            text = line["text"].strip()
            if not text:
                continue
            if not (_EARLY_ALLEGATION_RE.search(text) or _CONCLUSION_RE.match(text)):
                continue
            if not _CITE_RE.search(text):
                continue

            key = (line["page_no"], line["line_no"], line["text"])
            if key not in seen:
                seen.add(key)
                spans.append(
                    {
                        "text": line["text"],
                        "page_no": line["page_no"],
                        "line_no": line["line_no"],
                    }
                )

            citations = _LEAD_CITE_RE.findall(text)
            if "§§" in text or "sections " in text.lower():
                citations.extend(_FOLLOW_CITE_RE.findall(text))

            deduped = []
            for citation in citations:
                if citation not in deduped:
                    deduped.append(citation)

            for citation in deduped:
                nested_levels = citation.count("(")
                if len(deduped) > 1 or nested_levels >= 2:
                    synth_key = ("synthetic", citation)
                    if synth_key in seen:
                        continue
                    seen.add(synth_key)
                    spans.append({"text": f"49 CFR § {citation}"})
        return spans
    except Exception:
        return []

def _coerce_span(entry: Any) -> dict[str, Any] | None:
    if isinstance(entry, str):
        text = entry.strip()
        return {"text": text} if text else None
    if not isinstance(entry, dict):
        return None
    text = entry.get("text")
    if text is None:
        return None
    text = str(text)
    if not text.strip():
        return None
    coerced = dict(entry)
    coerced["text"] = text
    return coerced


def _span_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no"),
        span.get("paragraph_no"),
        span.get("line_no"),
        span.get("text"),
    )


def _sort_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no", 10**9),
        span.get("paragraph_no", 10**9),
        span.get("line_no", 10**9),
        span.get("text", ""),
    )


def _list_rule_files(rules_dir: Path, rule_names: list[str] | None = None) -> list[Path]:
    if rule_names:
        files = [rules_dir / f"{name}.py" for name in rule_names]
        return [path for path in files if path.exists()]
    return sorted(path for path in rules_dir.glob("rule_*.py") if path.is_file())


def _apply_rule_files(document: dict[str, Any], rule_files: list[Path]) -> dict[str, Any]:
    spans: list[dict[str, Any]] = []
    rules_applied: list[str] = []
    rules_no_hits: list[str] = []
    rule_errors: list[str] = []

    for rule_file in rule_files:
        rule_name = rule_file.stem
        try:
            rule_fn = _load_rule_fn(rule_file)
            raw_result = rule_fn(document)
        except Exception as exc:
            rule_errors.append(f"{rule_name}: {exc}")
            rules_no_hits.append(rule_name)
            continue

        if not isinstance(raw_result, list):
            rules_no_hits.append(rule_name)
            continue

        coerced = [_coerce_span(item) for item in raw_result]
        cleaned = [item for item in coerced if item]
        if cleaned:
            spans.extend(cleaned)
            rules_applied.append(rule_name)
        else:
            rules_no_hits.append(rule_name)

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[Any, ...]] = set()
    for span in spans:
        key = _span_key(span)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(span)

    deduped.sort(key=_sort_key)
    retrieved_text = "\n\n".join(span["text"] for span in deduped) if deduped else ""

    return {
        "retrieved_spans": deduped,
        "retrieved_text": retrieved_text,
        "retrieved_token_count": _count_tokens(retrieved_text),
        "rules_applied": rules_applied,
        "rules_no_hits": rules_no_hits,
        "rule_errors": rule_errors,
    }


def _qa_call(question: str, retrieved_text: str, *, model_name: str = "gpt54") -> tuple[str | None, int, int, float]:
    model_mod = importlib.import_module(f"models.{model_name}")
    t0 = time.time()
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {"role": "system", "content": _QA_SYSTEM},
            {"role": "user", "content": f"Passage:\n{retrieved_text}\n\nQuestion: {question}"},
        ],
        max_completion_tokens=500,
        temperature=0.0,
    )
    latency = round(time.time() - t0, 3)
    answer = (response.choices[0].message.content or "").strip() or None
    usage = response.usage
    return (
        answer,
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
        latency,
    )


def _judge_call(
    dataset_name: str,
    question: str,
    ground_truth: Any,
    predicted: Any,
) -> tuple[bool, int, int]:
    if ground_truth is None or predicted is None:
        return False, 0, 0

    model_mod = importlib.import_module("models.gpt54")
    gt_str = json.dumps(ground_truth) if not isinstance(ground_truth, str) else ground_truth
    pred_str = str(predicted)
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {
                "role": "system",
                "content": _JUDGE_SYSTEM_BY_DATASET.get(dataset_name, _JUDGE_SYSTEM_GENERIC),
            },
            {
                "role": "user",
                "content": f"Question: {question}\nGround Truth: {gt_str}\nPredicted: {pred_str}",
            },
        ],
        max_completion_tokens=10,
        temperature=0.0,
    )
    verdict = (response.choices[0].message.content or "").strip().lower()
    usage = response.usage
    return (
        verdict == "correct",
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
    )


def _clean_stderr(stderr: str) -> str:
    lines = [
        line
        for line in stderr.splitlines()
        if line.strip() != "Reading additional input from stdin..."
    ]
    return "\n".join(lines).strip()[:4000]


def _parse_done_output(text: str) -> str | None:
    for line in text.splitlines():
        line = line.strip()
        if line.startswith("AGENTIC_RULE_FULL_DATA_DONE"):
            rest = line[len("AGENTIC_RULE_FULL_DATA_DONE") :].strip()
            if rest.startswith("report="):
                return rest[len("report=") :].strip()
    return None


def _parse_codex_events(jsonl_text: str) -> dict[str, Any]:
    usage_totals = {
        "input_tokens": 0,
        "output_tokens": 0,
        "cached_input_tokens": 0,
        "reasoning_output_tokens": 0,
    }
    thread_id: str | None = None
    error_message: str | None = None
    event_count = 0

    for raw_line in jsonl_text.splitlines():
        raw_line = raw_line.strip()
        if not raw_line:
            continue
        try:
            event = json.loads(raw_line)
        except json.JSONDecodeError:
            continue
        event_count += 1
        if event.get("type") == "thread.started":
            thread_id = event.get("thread_id")
        elif event.get("type") == "turn.completed":
            usage = event.get("usage") or {}
            for key in usage_totals:
                usage_totals[key] += int(usage.get(key) or 0)
        elif event.get("type") in {"error", "turn.failed"}:
            error_message = event.get("message") or str(event.get("error") or "")

    return {
        "usage_totals": usage_totals,
        "thread_id": thread_id,
        "error_message": error_message,
        "event_count": event_count,
    }


def _load_json(path: Path, default: Any) -> Any:
    if not path.exists():
        return default
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


def _write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def _relpath(path: Path) -> str:
    try:
        return str(path.relative_to(_ROOT))
    except ValueError:
        return str(path)


def _ledger_load(ledger_path: Path) -> dict[str, Any]:
    return _load_json(ledger_path, {"verify_accuracy_calls": []})


def _ledger_append_verify(ledger_path: Path, entry: dict[str, Any]) -> dict[str, Any]:
    ledger = _ledger_load(ledger_path)
    calls = ledger.setdefault("verify_accuracy_calls", [])
    calls.append(entry)
    _write_json(ledger_path, ledger)
    return ledger


def _manifest_docs(manifest: dict[str, Any]) -> dict[str, Path]:
    return {
        entry["doc_name"]: Path(entry["doc_path"])
        for entry in manifest.get("documents", [])
    }


def _manifest_ground_truth(manifest: dict[str, Any]) -> dict[str, Any]:
    return {
        entry["doc_name"]: entry.get("ground_truth")
        for entry in manifest.get("documents", [])
    }


def _verify_accuracy_on_docs(
    *,
    manifest: dict[str, Any],
    doc_names: list[str],
    rule_names: list[str] | None = None,
) -> dict[str, Any]:
    docs_map = _manifest_docs(manifest)
    gt_map = _manifest_ground_truth(manifest)
    rules_dir = Path(manifest["rules_dir"])
    question = manifest["question"]
    dataset_name = manifest["dataset"]
    rule_files = _list_rule_files(rules_dir, rule_names)

    results: list[dict[str, Any]] = []
    total_qa_in = 0
    total_qa_out = 0
    total_judge_in = 0
    total_judge_out = 0
    total_latency = 0.0
    cost_ratios: list[float] = []

    for doc_name in doc_names:
        doc_path = docs_map[doc_name]
        document = _load_txt_doc(doc_name, doc_path)
        applied = _apply_rule_files(document, rule_files)
        answer, qa_in, qa_out, latency = _qa_call(question, applied["retrieved_text"], model_name="gpt54")
        correct, judge_in, judge_out = _judge_call(dataset_name, question, gt_map.get(doc_name), answer)
        doc_tokens = _count_tokens(document["text"])
        cost_ratio = applied["retrieved_token_count"] / doc_tokens if doc_tokens > 0 else 0.0

        total_qa_in += qa_in
        total_qa_out += qa_out
        total_judge_in += judge_in
        total_judge_out += judge_out
        total_latency += latency
        cost_ratios.append(cost_ratio)

        results.append(
            {
                "doc_name": doc_name,
                "answer": answer,
                "correct": correct,
                "retrieved_token_count": applied["retrieved_token_count"],
                "cost_ratio": round(cost_ratio, 6),
                "rules_applied": applied["rules_applied"],
            }
        )

    n = len(results)
    n_correct = sum(1 for item in results if item["correct"])
    accuracy = (n_correct / n) if n else 0.0
    return {
        "doc_names": doc_names,
        "rule_names": [path.stem for path in rule_files],
        "n": n,
        "n_correct": n_correct,
        "accuracy": round(accuracy, 6),
        "avg_cost_ratio": round(sum(cost_ratios) / n, 6) if n else 0.0,
        "qa_input_tokens": total_qa_in,
        "qa_output_tokens": total_qa_out,
        "judge_input_tokens": total_judge_in,
        "judge_output_tokens": total_judge_out,
        "input_tokens_total": total_qa_in + total_judge_in,
        "output_tokens_total": total_qa_out + total_judge_out,
        "latency_seconds": round(total_latency, 3),
        "results": results,
    }


def _summarize_rule_hits(
    *,
    manifest: dict[str, Any],
    rule_name: str,
) -> dict[str, Any]:
    docs_map = _manifest_docs(manifest)
    rules_dir = Path(manifest["rules_dir"])
    rule_files = _list_rule_files(rules_dir, [rule_name])
    if not rule_files:
        raise FileNotFoundError(f"Rule not found: {rule_name}")

    hits: list[dict[str, Any]] = []
    cost_ratios: list[float] = []

    for doc_name, doc_path in docs_map.items():
        document = _load_txt_doc(doc_name, doc_path)
        applied = _apply_rule_files(document, rule_files)
        doc_tokens = _count_tokens(document["text"])
        ratio = applied["retrieved_token_count"] / doc_tokens if doc_tokens > 0 else 0.0
        cost_ratios.append(ratio)
        hits.append(
            {
                "doc_name": doc_name,
                "hit": bool(applied["retrieved_text"]),
                "retrieved_token_count": applied["retrieved_token_count"],
                "cost_ratio": round(ratio, 6),
            }
        )

    return {
        "rule_name": rule_name,
        "hit_count": sum(1 for item in hits if item["hit"]),
        "doc_count": len(hits),
        "avg_cost_ratio": round(sum(cost_ratios) / len(cost_ratios), 6) if hits else 0.0,
        "hits": hits,
    }

