{
  "rule_name": "rule_statutory_debt_limit_suspended",
  "file": "/mnt/data/LSF/rules/officeqa/agentic_rule_full_data_gpt54_adaptive/all_docs/q12_is_the_statutory_debt_limit_currently_suspended_or_set_at_a_/rule_statutory_debt_limit_suspended.py",
  "code": "def rule_statutory_debt_limit_suspended(doc: dict) -> list[dict]:\n    try:\n        import re\n\n        lines = doc.get(\"lines\") or []\n        paragraphs = doc.get(\"paragraphs\") or []\n        spans = []\n        seen = set()\n\n        suspend_re = re.compile(r\"\\bsuspend(?:ed|sion|ing)?\\b\", re.I)\n        key_re = re.compile(r\"(statutory debt limit|debt limit|borrowing limit|debt ceiling)\", re.I)\n\n        def add_span(text: str, meta: dict) -> None:\n            text = (text or \"\").strip()\n            if not text:\n                return\n            key = (\n                meta.get(\"page_no\"),\n                meta.get(\"line_no\"),\n                meta.get(\"paragraph_no\"),\n                text,\n            )\n            if key in seen:\n                return\n            seen.add(key)\n            span = dict(meta)\n            span[\"text\"] = text\n            spans.append(span)\n\n        for para in paragraphs:\n            text = (para.get(\"text\") or \"\").strip()\n            if not text:\n                continue\n            if suspend_re.search(text) and key_re.search(text):\n                add_span(\n                    text,\n                    {\n                        \"page_no\": para.get(\"page_no\"),\n                        \"paragraph_no\": para.get(\"paragraph_no\"),\n                    },\n                )\n\n        for idx, line in enumerate(lines):\n            text = (line.get(\"text\") or \"\").strip()\n            lo = text.lower()\n            if not text:\n                continue\n\n            direct_hit = False\n            if suspend_re.search(text) and key_re.search(text):\n                direct_hit = True\n            elif \"borrowing limit\" in lo and suspend_re.search(text):\n                direct_hit = True\n\n            if not direct_hit:\n                continue\n\n            start = idx\n            end = min(len(lines), idx + 3)\n            window = []\n            for item in lines[start:end]:\n                item_text = (item.get(\"text\") or \"\").rstrip()\n                if item_text:\n                    window.append(item_text)\n            if window:\n                add_span(\n                    \"\\n\".join(window),\n                    {\n                        \"page_no\": line.get(\"page_no\"),\n                        \"line_no\": line.get(\"line_no\"),\n                    },\n                )\n\n        return spans[:4]\n    except Exception:\n        return []\n",
